#!/usr/bin/env python3
from pathlib import Path

engine = Path('.github/clean07/RedLightDiscoveryEngine.java')
text = engine.read_text()

old_stats = '''    static final class ProgramStats {\n        boolean available;\n        int inserted;\n        int artwork;\n    }\n'''
new_stats = '''    static final class ProgramStats {\n        boolean available;\n        boolean changed;\n        int total;\n        int inserted;\n        int updated;\n        int deleted;\n        int unchanged;\n        int artwork;\n    }\n\n    static final class ExistingProgram {\n        long id;\n        String identity, title, description, intentUri, posterArtUri;\n        int type, weight, posterAspectRatio;\n    }\n\n    static final class ExistingPrograms {\n        boolean available;\n        final LinkedHashMap<String, ExistingProgram> byIdentity = new LinkedHashMap<>();\n    }\n'''
if text.count(old_stats) != 1:
    raise SystemExit(f'CLEAN12.1 ProgramStats anchor mismatch: {text.count(old_stats)}')
text = text.replace(old_stats, new_stats, 1)

old_loop = '''            ArtworkCache art = ArtworkCache.open(c);\n            int channels = 0, populated = 0, totalPrograms = 0, totalArtwork = 0;\n            for (Section s : sections.values()) {\n                long channel = ensureChannel(c, s);\n                if (channel <= 0) {\n                    Log.i(TAG, "CLEAN07 CHANNEL FAILED key=" + s.key + " title=" + s.title);\n                    continue;\n                }\n                channels++;\n                ProgramStats ps = syncPrograms(c, channel, s, art);\n                if (ps.available) {\n                    if (ps.inserted > 0) populated++;\n                    totalPrograms += ps.inserted;\n                    totalArtwork += ps.artwork;\n                }\n                Log.i(TAG, "CLEAN07 CHANNEL key=" + s.key + " id=" + channel\n                        + " programs=" + ps.inserted + " artwork=" + ps.artwork\n                        + " title=" + s.title);\n            }\n            if (art != null) art.close();\n\n            Log.i(TAG, "CLEAN07 SUCCESS channels=" + channels\n                    + " populated=" + populated\n                    + " programs=" + totalPrograms\n                    + " artwork=" + totalArtwork);\n'''
new_loop = '''            ArtworkCache art = ArtworkCache.open(c);\n            int channels = 0, populated = 0, totalPrograms = 0, totalArtwork = 0;\n            int totalInserted = 0, totalUpdated = 0, totalDeleted = 0, totalUnchanged = 0;\n            for (Section s : sections.values()) {\n                long channel = ensureChannel(c, s);\n                if (channel <= 0) {\n                    Log.i(TAG, "CLEAN07 CHANNEL FAILED key=" + s.key + " title=" + s.title);\n                    continue;\n                }\n                channels++;\n                ProgramStats ps = syncPrograms(c, channel, s, art);\n                if (ps.available) {\n                    if (ps.total > 0) populated++;\n                    totalPrograms += ps.total;\n                    totalArtwork += ps.artwork;\n                    totalInserted += ps.inserted;\n                    totalUpdated += ps.updated;\n                    totalDeleted += ps.deleted;\n                    totalUnchanged += ps.unchanged;\n                }\n                Log.i(TAG, "CLEAN12.1 CHANNEL key=" + s.key + " id=" + channel\n                        + " programs=" + ps.total + " artwork=" + ps.artwork\n                        + " inserted=" + ps.inserted + " updated=" + ps.updated\n                        + " deleted=" + ps.deleted + " unchanged=" + ps.unchanged\n                        + " changed=" + ps.changed + " title=" + s.title);\n            }\n            if (art != null) art.close();\n\n            Log.i(TAG, "CLEAN12.1 SUCCESS channels=" + channels\n                    + " populated=" + populated\n                    + " programs=" + totalPrograms\n                    + " artwork=" + totalArtwork\n                    + " inserted=" + totalInserted\n                    + " updated=" + totalUpdated\n                    + " deleted=" + totalDeleted\n                    + " unchanged=" + totalUnchanged);\n'''
if text.count(old_loop) != 1:
    raise SystemExit(f'CLEAN12.1 sync aggregate anchor mismatch: {text.count(old_loop)}')
text = text.replace(old_loop, new_loop, 1)

old_sync = '''    private static ProgramStats syncPrograms(Context c, long channel, Section section, ArtworkCache art) {\n        ProgramStats stats = new ProgramStats();\n        List<Entry> entries = list(c, section.uri);\n        if (entries == null) return stats; // Keep cached cards during a transient Kodi/provider failure.\n        stats.available = true;\n        deleteProgramsForChannel(c, channel);\n\n        int n = 0;\n        for (Entry e : entries) {\n            if (n >= MAX_PROGRAMS) break;\n            if (e.dir() && !raw(e.uri).contains("tmdb_id=")) continue;\n\n            ContentValues v = new ContentValues();\n            v.put("channel_id", channel);\n            v.put("title", e.name);\n            v.put("description", e.mediaType != null ? e.mediaType : "Red Light");\n            v.put("type", programType(e));\n            v.put("intent_uri", programIdentityIntent(c, raw(e.uri)).toUri(0));\n            v.put("internal_provider_id", raw(e.uri));\n            v.put("weight", MAX_PROGRAMS - n);\n            v.put("poster_art_aspect_ratio", 5);\n            String poster = art == null ? null : art.posterFor(e);\n            if (poster != null && !poster.isEmpty()) {\n                v.put("poster_art_uri", poster);\n                stats.artwork++;\n            }\n            try {\n                if (c.getContentResolver().insert(TvContract.PreviewPrograms.CONTENT_URI, v) != null) {\n                    n++;\n                    stats.inserted++;\n                }\n            } catch (Throwable t) {\n                Log.i(TAG, "CLEAN07 preview insert failed key=" + section.key + " title=" + e.name);\n            }\n        }\n        return stats;\n    }\n\n    private static void deleteProgramsForChannel(Context c, long channel) {\n        int removed = 0;\n        try (Cursor cur = c.getContentResolver().query(TvContract.PreviewPrograms.CONTENT_URI,\n                new String[]{"_id", "channel_id"}, null, null, null)) {\n            if (cur != null) while (cur.moveToNext()) {\n                if (cur.getLong(1) != channel) continue;\n                long id = cur.getLong(0);\n                try {\n                    removed += c.getContentResolver().delete(\n                            ContentUris.withAppendedId(TvContract.PreviewPrograms.CONTENT_URI, id), null, null);\n                } catch (Throwable ignored) {}\n            }\n        } catch (Throwable t) {\n            Log.i(TAG, "CLEAN07 preview cleanup unavailable channelId=" + channel);\n        }\n        Log.i(TAG, "CLEAN07 PROGRAM CLEANUP channelId=" + channel + " removed=" + removed);\n    }\n'''
new_sync = '''    private static ProgramStats syncPrograms(Context c, long channel, Section section, ArtworkCache art) {\n        ProgramStats stats = new ProgramStats();\n        List<Entry> entries = list(c, section.uri);\n        if (entries == null) return stats; // Keep cached cards during a transient Kodi/provider failure.\n\n        ExistingPrograms existing = loadExistingPrograms(c, channel);\n        if (!existing.available) {\n            Log.i(TAG, "CLEAN12.1 existing-program query unavailable; cached row retained key=" + section.key);\n            return stats;\n        }\n        stats.available = true;\n\n        Set<String> desired = new HashSet<>();\n        int n = 0;\n        for (Entry e : entries) {\n            if (n >= MAX_PROGRAMS) break;\n            String identity = raw(e.uri);\n            if (e.dir() && !identity.contains("tmdb_id=")) continue;\n            if (!desired.add(identity)) continue;\n\n            ContentValues v = new ContentValues();\n            v.put("channel_id", channel);\n            v.put("title", e.name);\n            v.put("description", e.mediaType != null ? e.mediaType : "Red Light");\n            v.put("type", programType(e));\n            v.put("intent_uri", programIdentityIntent(c, identity).toUri(0));\n            v.put("internal_provider_id", identity);\n            v.put("weight", MAX_PROGRAMS - n);\n            v.put("poster_art_aspect_ratio", 5);\n            String poster = art == null ? null : art.posterFor(e);\n            if (poster != null && !poster.isEmpty()) {\n                v.put("poster_art_uri", poster);\n                stats.artwork++;\n            }\n\n            ExistingProgram old = existing.byIdentity.remove(identity);\n            try {\n                if (old == null) {\n                    if (c.getContentResolver().insert(TvContract.PreviewPrograms.CONTENT_URI, v) != null) {\n                        stats.inserted++;\n                        stats.total++;\n                        stats.changed = true;\n                    }\n                } else if (sameProgram(old, v)) {\n                    stats.unchanged++;\n                    stats.total++;\n                } else {\n                    int changed = c.getContentResolver().update(\n                            ContentUris.withAppendedId(TvContract.PreviewPrograms.CONTENT_URI, old.id),\n                            v, null, null);\n                    if (changed > 0) {\n                        stats.updated++;\n                        stats.changed = true;\n                    } else {\n                        Log.i(TAG, "CLEAN12.1 preview update returned 0 key=" + section.key\n                                + " title=" + e.name);\n                    }\n                    // Even if Android reports a zero-row update, the old card still exists.\n                    stats.total++;\n                }\n            } catch (Throwable t) {\n                Log.i(TAG, "CLEAN12.1 preview upsert failed key=" + section.key + " title=" + e.name);\n                if (old != null) stats.total++;\n            }\n            n++;\n        }\n\n        // Anything left in the channel was not published by Red Light this time. Synthetic\n        // duplicate keys created by loadExistingPrograms also land here and are cleaned up.\n        for (ExistingProgram stale : existing.byIdentity.values()) {\n            try {\n                int removed = c.getContentResolver().delete(\n                        ContentUris.withAppendedId(TvContract.PreviewPrograms.CONTENT_URI, stale.id),\n                        null, null);\n                if (removed > 0) {\n                    stats.deleted += removed;\n                    stats.changed = true;\n                }\n            } catch (Throwable ignored) {}\n        }\n        return stats;\n    }\n\n    private static ExistingPrograms loadExistingPrograms(Context c, long channel) {\n        ExistingPrograms out = new ExistingPrograms();\n        String[] projection = {\n                "_id", "channel_id", "internal_provider_id", "title", "description",\n                "type", "intent_uri", "weight", "poster_art_uri", "poster_art_aspect_ratio"\n        };\n        try (Cursor cur = c.getContentResolver().query(\n                TvContract.PreviewPrograms.CONTENT_URI, projection, null, null, null)) {\n            if (cur == null) return out;\n            while (cur.moveToNext()) {\n                if (cur.getLong(1) != channel) continue;\n                ExistingProgram p = new ExistingProgram();\n                p.id = cur.getLong(0);\n                p.identity = cur.isNull(2) ? "" : cur.getString(2);\n                p.title = cur.isNull(3) ? "" : cur.getString(3);\n                p.description = cur.isNull(4) ? "" : cur.getString(4);\n                p.type = cur.isNull(5) ? 0 : cur.getInt(5);\n                p.intentUri = cur.isNull(6) ? "" : cur.getString(6);\n                p.weight = cur.isNull(7) ? 0 : cur.getInt(7);\n                p.posterArtUri = cur.isNull(8) ? "" : cur.getString(8);\n                p.posterAspectRatio = cur.isNull(9) ? 0 : cur.getInt(9);\n\n                String key = p.identity;\n                if (key == null || key.isEmpty()) key = "__missing_identity__:" + p.id;\n                if (out.byIdentity.containsKey(key)) key = key + "__duplicate__:" + p.id;\n                out.byIdentity.put(key, p);\n            }\n            out.available = true;\n        } catch (Throwable t) {\n            Log.i(TAG, "CLEAN12.1 preview query unavailable channelId=" + channel);\n        }\n        return out;\n    }\n\n    private static boolean sameProgram(ExistingProgram old, ContentValues v) {\n        if (!same(old.title, v.getAsString("title"))) return false;\n        if (!same(old.description, v.getAsString("description"))) return false;\n        if (old.type != intValue(v, "type")) return false;\n        if (!same(old.intentUri, v.getAsString("intent_uri"))) return false;\n        if (old.weight != intValue(v, "weight")) return false;\n        if (old.posterAspectRatio != intValue(v, "poster_art_aspect_ratio")) return false;\n        // If artwork lookup is temporarily unavailable, preserve the existing poster rather\n        // than treating the missing lookup as a request to clear artwork.\n        if (v.containsKey("poster_art_uri")\n                && !same(old.posterArtUri, v.getAsString("poster_art_uri"))) return false;\n        return true;\n    }\n\n    private static int intValue(ContentValues v, String key) {\n        Integer x = v.getAsInteger(key);\n        return x == null ? 0 : x;\n    }\n\n    private static boolean same(String a, String b) {\n        return a == null ? b == null : a.equals(b);\n    }\n'''
if text.count(old_sync) != 1:
    raise SystemExit(f'CLEAN12.1 syncPrograms anchor mismatch: {text.count(old_sync)}')
text = text.replace(old_sync, new_sync, 1)

engine.write_text(text)

check = engine.read_text()
for token in [
    'CLEAN12.1 SUCCESS channels=',
    'CLEAN12.1 CHANNEL key=',
    'loadExistingPrograms(c, channel)',
    'sameProgram(old, v)',
    'inserted=" + ps.inserted + " updated=" + ps.updated',
    'deleted=" + ps.deleted + " unchanged=" + ps.unchanged',
    '__duplicate__:',
    'preserve the existing poster',
]:
    if token not in check:
        raise SystemExit('CLEAN12.1 source verification failed: ' + token)

if 'deleteProgramsForChannel(c, channel)' in check:
    raise SystemExit('CLEAN12.1 destructive programme cleanup still active')

print('PASS: CLEAN12.1 differential PreviewProgram sync prepared')
